python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_1960_12.json'))
elements = data['document']['elements']
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        print(f'Element {i}: description={el.get(\"description\", \"\")[:200]}')
        content = el.get('content')
        if content:
            print(f'Content: {str(content)[:800]}')
        print('---')
        if i > 3:
            break"
